int ExportRecordInfoDao::CreateTableSQLite3(chen::IDB::ptr conn) {
    return conn->execute("CREATE TABLE IF NOT EXISTS export_record("
            "id INTEGER PRIMARY KEY AUTOINCREMENT,"
            "name TEXT NOT NULL DEFAULT '',"
            "type TEXT NOT NULL DEFAULT '',"
            "format TEXT NOT NULL DEFAULT 'json',"
            "size INTEGER NOT NULL DEFAULT 0,"
            "record_count INTEGER NOT NULL DEFAULT 0,"
            "file_path TEXT NOT NULL DEFAULT '',"
            "status TEXT NOT NULL DEFAULT 'processing',"
            "created_by INTEGER NOT NULL DEFAULT 0,"
            "is_deleted INTEGER NOT NULL DEFAULT 0,"
            "create_time TIMESTAMP NOT NULL DEFAULT current_timestamp);"
            "CREATE INDEX IF NOT EXISTS export_record_type ON export_record(type);"
            "CREATE INDEX IF NOT EXISTS export_record_status ON export_record(status);"
            "CREATE INDEX IF NOT EXISTS export_record_created_by ON export_record(created_by);"
            );
}

